export class Controls{constructor(game,rotate,cb={}){this.game=game;this.rotate=rotate;this.cb=cb;this.held=new Map();this.das=145;this.arr=48;window.addEventListener('keydown',e=>this.keyDown(e));window.addEventListener('keyup',e=>this.held.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>this.held.clear());document.addEventListener('visibilitychange',()=>{this.held.clear();if(document.hidden)this.cb.autoPause?.();});document.querySelectorAll('[data-action]').forEach(b=>{const a=b.dataset.action;const end=()=>{clearTimeout(b._timer);clearInterval(b._repeat);};b.addEventListener('pointerdown',e=>{e.preventDefault();if(a==='rotate')this.rotate(true);else if(a==='drop')this.game.hardDrop();else if(a==='hold')this.game.holdPiece();else{this.act(a);b._timer=setTimeout(()=>{b._repeat=setInterval(()=>this.act(a),this.arr);},this.das);}this.cb.changed?.();});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,end));});}
keyDown(e){const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowdown','arrowup',' ','spacebar'].includes(k))e.preventDefault();if(e.repeat)return;if(k==='enter'){this.cb.start?.();return;}if(k==='p'||k==='escape'){this.cb.pause?.();return;}if(k==='r'){this.cb.restart?.();return;}if(k==='m'){this.cb.sound?.();return;}if(k==='arrowleft'||k==='arrowright'||k==='arrowdown'){const a=k==='arrowleft'?'left':k==='arrowright'?'right':'down';this.act(a);this.held.set(k,{a,elapsed:0,next:this.das});return;}if(k==='arrowup'||k==='x'){this.rotate(true);this.cb.changed?.();return;}if(k==='z'){this.rotate(false);this.cb.changed?.();return;}if(k===' '||k==='spacebar'){this.game.hardDrop();this.cb.changed?.();return;}if(k==='c'){this.game.holdPiece();this.cb.changed?.();}}
act(a){if(a==='left')this.game.move(-1);if(a==='right')this.game.move(1);if(a==='down')this.game.move(0,1);this.cb.changed?.();}
update(dt){for(const item of this.held.values()){item.elapsed+=dt;if(item.elapsed>=item.next){this.act(item.a);item.next+=this.arr;}}}}
